package com.assetsphere.modules.workspace.domain;
import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import lombok.Getter; import com.assetsphere.modules.common.BaseEntity;
@Getter @Entity @Table(name="workspace_invitations") public class WorkspaceInvitation extends BaseEntity { @Column(name="workspace_id",nullable=false) private UUID workspaceId; @Column(name="invitee_email",nullable=false,length=320) private String inviteeEmail; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private WorkspaceRole role; @Column(name="token_hash",nullable=false,unique=true,length=64) private String tokenHash; @Column(name="invited_by_user_id",nullable=false) private UUID invitedByUserId; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="accepted_at") private Instant acceptedAt; @Column(name="revoked_at") private Instant revokedAt; @Enumerated(EnumType.STRING) @Column(nullable=false,length=32) private InvitationStatus status; protected WorkspaceInvitation(){} public WorkspaceInvitation(UUID workspaceId,String inviteeEmail,WorkspaceRole role,String tokenHash,UUID invitedByUserId,Instant expiresAt){this.workspaceId=workspaceId;this.inviteeEmail=inviteeEmail;this.role=role;this.tokenHash=tokenHash;this.invitedByUserId=invitedByUserId;this.expiresAt=expiresAt;this.status=InvitationStatus.PENDING;} public boolean isExpired(Instant now){return !expiresAt.isAfter(now);} public void accept(Instant now){status=InvitationStatus.ACCEPTED;acceptedAt=now;} public void expire(){status=InvitationStatus.EXPIRED;} public boolean isPending(){return status==InvitationStatus.PENDING;} }
